// The TypeScript packages and their entry sources, for the checks that walk them: knip
// (`knip.config.ts`) and the undocumented-export check (`apps/docs/scripts/check-api-docs.mjs`).
// One build convention lives here: each export's `dist/**.js` is built from `src/**.ts`.
import { existsSync, readdirSync, readFileSync } from "node:fs";

/** Packages left out: @laminapdf/wasm's code and types are generated by wasm-bindgen. */
const GENERATED = new Set(["wasm"]);

/** Every `.js` file an `exports` map points at, each subpath and condition. */
function exportedFiles(exports) {
  if (typeof exports === "string") return exports.endsWith(".js") ? [exports] : [];
  if (exports === null || typeof exports !== "object") return [];
  return Object.values(exports).flatMap(exportedFiles);
}

/** The package folders under `root`/packages with a TypeScript build and `exports`, sorted. */
export function packageDirs(root) {
  return readdirSync(`${root}/packages`, { withFileTypes: true })
    .filter((d) => d.isDirectory() && !GENERATED.has(d.name))
    .map((d) => d.name)
    .filter((dir) => existsSync(`${root}/packages/${dir}/tsconfig.build.json`))
    .filter((dir) => manifest(root, dir).exports !== undefined)
    .sort();
}

/** A package's `package.json`. */
export function manifest(root, dir) {
  return JSON.parse(readFileSync(`${root}/packages/${dir}/package.json`, "utf8"));
}

/** A package's entry sources, relative to its folder: each exported `dist/**.js` as its `src/**.ts`. */
export function entrySources(root, dir) {
  const files = new Set(exportedFiles(manifest(root, dir).exports));
  return [...files].map((f) => f.replace(/^\.\/dist\//, "src/").replace(/\.js$/, ".ts"));
}
